async(from,to)=>{for(const scene of postManifest.scenes.slice(from,to)){await responsiveTab.playwright.getByRole('combobox',{name:'演示场景',exact:true}).selectOption(scene.key);let r=await postReady(responsiveTab,responsiveCdp);trueResponsive.push({scene:scene.key,expanded:false,width:r.width,height:r.height,entry:r.entry,overflow:r.overflow,brokenImages:r.brokenImages,mainRows:r.mainRows});for(let n=0;n<5;n++){await responsiveTab.playwright.locator('.stage [data-expand="post"]').click();r=await postReady(responsiveTab,responsiveCdp);responsiveActions.push({scene:scene.key,width:r.width,action:'open',iteration:n,elapsedMs:r.measurements.at(-1)?.elapsedMs});if(n===0)trueResponsive.push({scene:scene.key,expanded:true,width:r.width,height:r.height,entry:r.entry,overflow:r.overflow,brokenImages:r.brokenImages,postRows:r.postRows});await responsiveTab.playwright.locator('#branch-post .branch-head [data-expand="post"]').click();r=await postReady(responsiveTab,responsiveCdp);responsiveActions.push({scene:scene.key,width:r.width,action:'close',iteration:n,elapsedMs:r.measurements.at(-1)?.elapsedMs});}await fs.writeFile(postOut+'/responsive-views.json',JSON.stringify(trueResponsive,null,2));await fs.writeFile(postOut+'/responsive-actions.json',JSON.stringify(responsiveActions,null,2));}return{views:trueResponsive.length,actions:responsiveActions.length,max:Math.max(...responsiveActions.map(r=>r.elapsedMs))}}